      "element_id": "prisma_2020_12_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No thresholds or ranges for interpreting effect sizes (e.g., clinically important differences) or their rationale are reported; only statistical significance (P<0.05) and heterogeneity thresholds (I2>50%) are given, which do not address effect size interpretation."
    },
    {
      "element_id": "prisma_2020_12_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No methods for re-expressing synthesized results in another effect measure are described. The conversion of Cox regression results to log ORs is described as data extraction, not re-expression of pooled results."
    },
    {
      "element_id": "prisma_2020_12_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The choice of effect measures (OR, MD, RR, HR) is stated but no justification for selecting these measures is provided."
    }
  ],
  "confidence": 88
